def admit(active, waiting, budget, slots):
    # Validate that no waiting reservation exceeds the total budget
    for value in waiting:
        if value > budget:
            raise ValueError

    admitted = []
    current_budget = sum(active)
    remaining_slots = slots - len(active)

    # Process waiting reservations in FIFO order
    for value in waiting:
        if current_budget + value <= budget and remaining_slots > 0:
            admitted.append(value)
            current_budget += value
            remaining_slots -= 1
        else:
            break

    # Return (admitted, remaining) without modifying inputs
    # Need to be more careful about what's in 'remaining'
    remaining = []
    admitted_copy = admitted.copy()

    for v in waiting:
        if admitted_copy and v == admitted_copy[0]:
            admitted_copy.pop(0)
        else:
            remaining.append(v)

    return admitted, remaining

