def admit(active, waiting, budget, slots):
    admitted = []
    remaining = list(waiting)  # Create a copy to avoid modifying input

    total_active = sum(active)

    # Check if any waiting reservation by itself exceeds the budget
    for value in waiting:
        if value > budget:
            raise ValueError("Reservation exceeds total budget")

    # Admit reservations following FIFO policy
    active_count = len(active)  # Current number of active reservations

    for value in waiting:
        # Check if we have capacity in slots and budget
        current_total_reservations = active_count + len(admitted)
        if current_total_reservations < slots and total_active + sum(admitted) + value <= budget:
            admitted.append(value)
            remaining.remove(value)  # Remove from remaining
        else:
            # Stop when first reservation can't be admitted due to slots or budget
            break

    return admitted, remaining

