def admit(active, waiting, budget, slots):
    admitted = []

    # Check if any single waiting reservation would exceed the total budget 
    # when added to active reservations
    for value in waiting:
        if sum(active) + value > budget:
            raise ValueError

    # Process waiting reservations in FIFO order  
    active_count = len(active)
    for value in waiting:
        # Check if we can admit this reservation (within slots and budget limits)
        if active_count + len(admitted) < slots and sum(active) + sum(admitted) + value <= budget:
            admitted.append(value)
        else:
            # If we can't admit this one, stop processing (FIFO requirement)
            break

    remaining = [v for v in waiting if v not in admitted]
    return admitted, remaining
